from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Row-tile height and inner-column unroll factor.
# These are compile-time tuning knobs chosen to improve cache locality
# and expose instruction-level parallelism without changing semantics.
TILE_I   = 32
UNROLL_J = 4

@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    inv9: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # We only update the interior; the 1-cell-wide halo is never written.
    assert n > 2

    # Global indices for the current point and base column within a block.
    i_glob: size
    j_base: size
    j_glob: size

    for t in seq(0, tsteps):
        # Strip-mine the interior i-range [1, n-1) into tiles of height TILE_I.
        # This preserves the original lexicographic (i, j) order:
        # rows are still processed in increasing i, just grouped into tiles.
        for ii in seq(0, (n - 2 + TILE_I - 1) / TILE_I):
            for i_inner in seq(0, TILE_I):
                i_glob = 1 + ii * TILE_I + i_inner
                # Guard to skip iterations beyond the last interior row
                # when (n - 2) is not a multiple of TILE_I.
                if i_glob < n - 1:
                    # Within each interior row, process columns in small
                    # UNROLL_J-sized blocks. This "unrolls" j without
                    # changing the per-row left-to-right order.
                    for jb in seq(0, (n - 2 + UNROLL_J - 1) / UNROLL_J):
                        j_base = 1 + jb * UNROLL_J

                        for u in seq(0, UNROLL_J):
                            j_glob = j_base + u
                            # Skip out-of-range columns in the final block
                            # when (n - 2) is not a multiple of UNROLL_J.
                            if j_glob < n - 1:
                                # 9-point Gauss–Seidel stencil at (i_glob, j_glob),
                                # using multiplication by inv9 instead of
                                # division by 9.0 for strength reduction.
                                A[i_glob, j_glob] = inv9 * (
                                    A[i_glob - 1, j_glob - 1]
                                    + A[i_glob - 1, j_glob]
                                    + A[i_glob - 1, j_glob + 1]
                                    + A[i_glob,     j_glob - 1]
                                    + A[i_glob,     j_glob]
                                    + A[i_glob,     j_glob + 1]
                                    + A[i_glob + 1, j_glob - 1]
                                    + A[i_glob + 1, j_glob]
                                    + A[i_glob + 1, j_glob + 1]
                                )
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  DATA_TYPE inv9;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Precompute 1/9 once and pass it to the Exo kernel to avoid
     a floating-point division in the inner loop. */
  inv9 = (DATA_TYPE)1.0 / (DATA_TYPE)9.0;

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_seidel_2d(/*ctxt=*/NULL, tsteps, n,
                   (DATA_TYPE*)&inv9,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
