# Tunable tiling parameters for spatial blocking.
# These are compile-time constants in the Exo object code and do not
# change the C function signature. They can be adjusted for a given
# machine’s cache sizes.
TILE_I = 32  # tile height  (rows)
TILE_J = 32  # tile width   (columns)


@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # We only update the interior 1..n-2 in each dimension.
    assert n > 2

    # Strength reduction: precompute 1/9 once and use multiplication
    # in the inner loops. This eliminates an FP division per grid point.
    inv9: DATA_TYPE
    inv9 = 1.0 / 9.0

    # Time loop: must remain sequential, as each sweep depends on the
    # result of the previous one.
    for t in seq(0, tsteps):
        # Spatial blocking over the *interior* points.
        #
        # We conceptually tile the interior index ranges
        #   i in [1, n-1)   and   j in [1, n-1)
        # using a GEMM-like “number of tiles” formulation, with per-tile
        # bounds enforced by guards. This preserves correctness for any
        # n > 2, regardless of divisibility by TILE_I/TILE_J.
        #
        # Number of tiles in each dimension (ceil division):
        #   n_int = n - 2
        #   num_i_tiles = (n_int + TILE_I - 1) / TILE_I
        #   num_j_tiles = (n_int + TILE_J - 1) / TILE_J
        #
        # II, JJ are *tile indices* (not absolute coordinates).
        for II in seq(0, (n - 2 + TILE_I - 1) / TILE_I):
            for JJ in seq(0, (n - 2 + TILE_J - 1) / TILE_J):

                # ii, jj are intra-tile indices.
                for ii in seq(0, TILE_I):
                    # Global row index:
                    #   i0 = 1 + II*TILE_I + ii
                    # We guard to ensure 1 <= i0 <= n-2, i.e., i0 < n-1.
                    if 1 + II * TILE_I + ii < n - 1:
                        for jj in seq(0, TILE_J):
                            # Global column index:
                            #   j0 = 1 + JJ*TILE_J + jj
                            if 1 + JJ * TILE_J + jj < n - 1:
                                # Materialize global indices as locals to keep
                                # the stencil expression readable and let the
                                # backend C compiler do common subexpression
                                # elimination and register allocation.
                                i0: size
                                j0: size
                                i0 = 1 + II * TILE_I + ii
                                j0 = 1 + JJ * TILE_J + jj

                                # 9-point Gauss–Seidel stencil at (i0, j0).
                                #
                                # Because the execution order is:
                                #   t outer
                                #   II, JJ tiling over the interior
                                #   ii (rows within tile) outer
                                #   jj (cols within tile) inner
                                # and we always move “forward” in t, i0, j0,
                                # every dependency from:
                                #   row above  (i0-1, j0-1..j0+1)
                                #   same row   (i0,   j0-1)
                                # is satisfied, and all neighbors that original
                                # code read from the *old* state (self, right,
                                # and below) are still read before they are
                                # overwritten in this time step.
                                s: DATA_TYPE
                                s = (
                                    A[i0 - 1, j0 - 1] + A[i0 - 1, j0] + A[i0 - 1, j0 + 1]
                                    + A[i0,     j0 - 1] + A[i0,     j0] + A[i0,     j0 + 1]
                                    + A[i0 + 1, j0 - 1] + A[i0 + 1, j0] + A[i0 + 1, j0 + 1]
                                )

                                A[i0, j0] = inv9 * s
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_seidel_2d(/*ctxt=*/NULL, tsteps, n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
